import{_ as t,H as s,f as n,i as e}from"./chunks/framework.nyB-Xt5O.js";const u=JSON.parse('{"title":"IP 4. Case Study","description":"","frontmatter":{},"headers":[],"relativePath":"interview/ip-4-case-study/index.md","filePath":"interview/ip-4-case-study/index.md","lastUpdated":1779798726000}'),d={name:"interview/ip-4-case-study/index.md"};function p(l,a,i,r,o,c){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="ip-4-case-study" tabindex="-1">IP 4. Case Study <a class="header-anchor" href="#ip-4-case-study" aria-label="Permalink to &quot;IP 4. Case Study&quot;">​</a></h1><blockquote><p>Case Study 是数据分析面试中最能体现候选人思维深度和结构化的环节，通常在业务面中占据核心地位。本章提供分析框架 + 典型案例，帮助你建立系统的 Case Study 方法论。</p></blockquote><h2 id="五大类型" tabindex="-1">五大类型 <a class="header-anchor" href="#五大类型" aria-label="Permalink to &quot;五大类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>核心能力</th><th>适用级别</th><th>题目示例</th></tr></thead><tbody><tr><td><a href="./01-metric-anomaly">指标异动分析</a></td><td>归因分析、假设驱动</td><td>初中级</td><td>DAU 下降 10% 如何分析</td></tr><tr><td><a href="./02-strategy-evaluation">业务策略评估</a></td><td>因果推断、实验设计</td><td>中高级</td><td>补贴活动效果评估</td></tr><tr><td><a href="./03-product-analysis">产品分析</a></td><td>产品思维、用户洞察</td><td>中高级</td><td>新功能采用率分析</td></tr><tr><td><a href="./04-fermi-estimation">费米估算</a></td><td>逻辑拆解、数量级估算</td><td>所有级别</td><td>估算北京有多少加油站</td></tr><tr><td><a href="./05-analytical-thinking">分析思路题</a></td><td>框架构建、假设验证</td><td>中高级</td><td>如何分析用户流失原因</td></tr></tbody></table><h2 id="通用分析框架-五步法" tabindex="-1">通用分析框架（五步法） <a class="header-anchor" href="#通用分析框架-五步法" aria-label="Permalink to &quot;通用分析框架（五步法）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 澄清问题 (Clarify)</span></span>
<span class="line"><span>   - 确认指标定义、时间范围、业务场景</span></span>
<span class="line"><span>   - 对齐预期：到底是什么问题？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 拆解框架 (Framework)</span></span>
<span class="line"><span>   - 按维度拆解（时间/地区/用户群/渠道）</span></span>
<span class="line"><span>   - 按公式拆解（漏斗分解/加法分解/乘法分解）</span></span>
<span class="line"><span>   - 按业务流程拆解</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 数据验证 (Analyze)</span></span>
<span class="line"><span>   - 锁定主要矛盾维度</span></span>
<span class="line"><span>   - 关联分析找原因</span></span>
<span class="line"><span>   - 排除法验证假设</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. 得出结论 (Conclude)</span></span>
<span class="line"><span>   - 根因总结（是什么、为什么）</span></span>
<span class="line"><span>   - 量化影响程度</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5. 行动建议 (Action)</span></span>
<span class="line"><span>   - 短期止血措施</span></span>
<span class="line"><span>   - 长期解决方案</span></span>
<span class="line"><span>   - 后续验证计划</span></span></code></pre></div><h2 id="面试评分维度" tabindex="-1">面试评分维度 <a class="header-anchor" href="#面试评分维度" aria-label="Permalink to &quot;面试评分维度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>权重</th><th>考察重点</th></tr></thead><tbody><tr><td>结构化思维</td><td>30%</td><td>是否有框架、逻辑是否清晰</td></tr><tr><td>业务理解</td><td>25%</td><td>对业务场景和指标的理解深度</td></tr><tr><td>量化分析</td><td>25%</td><td>是否用数据说话、能否做估算</td></tr><tr><td>表达沟通</td><td>20%</td><td>是否清晰、有条理、有亮点</td></tr></tbody></table><h2 id="练习建议" tabindex="-1">练习建议 <a class="header-anchor" href="#练习建议" aria-label="Permalink to &quot;练习建议&quot;">​</a></h2><ol><li><strong>先背框架再灵活运用</strong>：五步法是基础，但不要生搬硬套</li><li><strong>多积累业务场景</strong>：不同行业（电商/内容/金融/本地生活）的分析逻辑有差异</li><li><strong>动笔/动口练习</strong>：对着录音讲一遍，看自己是否逻辑自洽</li><li><strong>准备反问</strong>：面试结束前的反问环节也是加分项，准备 2-3 个有深度的问题</li></ol>`,10)])])}const b=t(d,[["render",p]]);export{u as __pageData,b as default};
